UPDATE yak_wf_task_instance SET state = #{runningState}, start_time = COALESCE(start_time, #{now}), next_retry_time = NULL, lock_version = lock_version + 1 WHERE id = #{taskInstanceId} AND state IN
#{state}
AND (next_retry_time IS NULL OR next_retry_time <= #{now})

UPDATE yak_wf_task_instance
SET state = #{stoppedState}, error_message = #{message}, end_time = #{endTime},
    lock_version = lock_version + 1
WHERE id = #{taskInstanceId}
  AND state NOT IN

    #{state}

UPDATE yak_wf_task_instance
SET state = #{skippedState}, error_message = #{reason}, end_time = #{endTime},
    lock_version = lock_version + 1
WHERE workflow_instance_id = #{workflowInstanceId}
  AND node_key IN

    #{nodeKey}

  AND state NOT IN

    #{state}

UPDATE yak_wf_task_instance
SET state = #{skippedState}, error_message = #{reason}, end_time = #{endTime},
    lock_version = lock_version + 1
WHERE workflow_instance_id = #{workflowInstanceId}
  AND state IN

    #{state}
